export function getButtonText(){const t=document.body.getAttribute("data-tpr-table-csv-download-text");return t||n}export function sanitizeFileName(n){if(!n)return"table-data";const t=n.trim().replace(/[^\w\s\-]/g,"").replace(/\s+/g,"-").toLowerCase();return t?t.length>50?t.substring(0,50):t:"table-data"}export function getCellText(n){return(n.innerText||n.textContent||"").replace(/\s+/g," ").trim()}export function escapeCsvValue(n){return n?(/^[=+\-@\t\r]/.test(n)&&(n="'"+n),/[,"\n\r]/.test(n))?'"'+n.replace(/"/g,'""')+'"':n:""}export function hasMergedCells(n){const t=n.querySelectorAll("th, td");for(let n=0;n<t.length;n++){const i=parseInt(t[n].getAttribute("colspan"),10),r=parseInt(t[n].getAttribute("rowspan"),10);if(i&&i>1||r&&r>1)return!0}return!1}function t(n,t){for(const i in n)if(parseInt(i,10)>=t&&n[i]>0)return!0;return!1}export function tableToCsv(n){const r=n.querySelectorAll("tr"),u=[],i={};for(let n=0;n<r.length;n++){const o=r[n].querySelectorAll("th, td"),e=[];let f=0,s=0;while(s<o.length||t(i,f)){if(i[f]>0){e[f]="";i[f]--;i[f]===0&&delete i[f];f++;continue}if(s<o.length){const n=o[s++],t=Math.max(1,parseInt(n.getAttribute("colspan"),10)||1),r=Math.max(1,parseInt(n.getAttribute("rowspan"),10)||1),u=escapeCsvValue(getCellText(n));for(let n=0;n<t;n++)e[f+n]=n===0?u:"",r>1&&(i[f+n]=r-1);f+=t;continue}e[f]="";f++}for(let n=0;n<e.length;n++)e[n]===undefined&&(e[n]="");u.push(e.join(","))}return u.join("\r\n")}export function downloadCsv(n,t){const u=new Blob(["﻿"+n],{type:"text/csv;charset=utf-8;"}),r=URL.createObjectURL(u),i=document.createElement("a");i.setAttribute("href",r);i.setAttribute("download",t+".csv");i.click();URL.revokeObjectURL(r)}export function hasExistingDownloadButton(n){const t=n.nextElementSibling;if(!t)return!1;if(t.hasAttribute("data-tpr-table-csv-button"))return!0;const i=t.classList.contains("tpr-table-download-form")?t:t.querySelector?t.querySelector(".tpr-table-download-form"):null;return i&&i.querySelector("button")?!0:!1}export function findServerSideDownloadForm(n){const t=n.nextElementSibling;if(!t)return null;if(t.classList.contains("tpr-table-download-form")&&t.querySelector("button"))return t;if(t.querySelector){const n=t.querySelector(".tpr-table-download-form");if(n&&n.querySelector("button"))return n}return null}export function initTableCsvDownload(){const t=getButtonText(),n=document.querySelectorAll(".govuk-table");for(let i=0;i<n.length;i++){const u=n[i],s=u.nextElementSibling;if(!s||!s.hasAttribute("data-tpr-table-csv-button")){const e=u.querySelector("caption"),o=sanitizeFileName(e?e.innerText||e.textContent:null),f=findServerSideDownloadForm(u);if(f){f.hasAttribute("data-tpr-table-csv-intercepted")||(f.setAttribute("data-tpr-table-csv-intercepted","true"),f.addEventListener("submit",n=>{n.preventDefault(),downloadCsv(tableToCsv(u),o)}));continue}const r=document.createElement("button");r.type="button";r.className="govuk-button govuk-button--secondary";r.setAttribute("data-module","govuk-button");r.setAttribute("data-tpr-table-csv-button","true");r.setAttribute("data-tpr-table-csv-filename",o);r.textContent=t;r.addEventListener("click",()=>{const n=tableToCsv(u);downloadCsv(n,o)});u.parentNode.insertBefore(r,u.nextSibling)}}}const n="Download table data (CSV)";document.readyState==="loading"?document.addEventListener("DOMContentLoaded",initTableCsvDownload):initTableCsvDownload();